103	export class People {
104	  protected readonly session = inject(Session);
105	  private readonly api = inject(PeopleApi);
106	  private readonly claimsApi = inject(ClaimsApi);
107	  private readonly ratesApi = inject(RatesApi);
108	  private readonly periodsApi = inject(PeriodsApi);
109	
110	  protected readonly grades = GRADES;
111	  protected readonly people = signal<Person[]>([]);
112	  /** The people the list shows: retired ones (any with a retirement date) only with "show retired" on. */
113	  protected readonly shownPeople = computed(() =>
114	    this.session.showRetired() ? this.people() : this.people().filter((p) => p.retiredFrom === null));
115	  /** Every claim on the sheet, newest first. */
116	  protected readonly claims = signal<Claim[]>([]);
117	  /** Each person's claims (newest first) and claimed in cents (OPEN and SETTLED claims only), by person id. */
118	  private readonly byPerson = computed(() => {
119	    const out = new Map<number, { claims: Claim[]; cents: number }>();
120	    for (const c of this.claims()) {
121	      const entry = out.get(c.personId) ?? { claims: [], cents: 0 };
122	      entry.claims.push(c);
123	      if (counts(c)) entry.cents += cents(c.amount);
124	      out.set(c.personId, entry);
125	    }
126	    return out;
127	  });
128	  /** The sheet's rates (a percent with two decimals), each for a grade from a from-date. */
129	  protected readonly rates = signal<Rate[]>([]);
130	  /** Each person's due-total in cents, by person id: the sum of the dues their OPEN and SETTLED
131	   *  claims show (each already rounded). Null (n/a) when their grade has no rate in force on the
132	   *  sheet's today, unless a settled claim keeps a fixed due or a stated claim a bound one: then
133	   *  the sum of the dues there are. */
134	  private readonly dueByPerson = computed(() => {
135	    const out = new Map<number, number | null>();
136	    for (const p of this.people()) {
137	      const rates = this.ratesOf(p.grade);
138	      const counted = this.claimsOf(p.id).filter(counts);
139	      if (pctOn(rates, this.session.today()) === null && !counted.some((c) => c.settledDue !== null || c.statedDue !== null)) {
140	        out.set(p.id, null);
141	        continue;
142	      }
143	      out.set(p.id, counted.reduce((sum, c) => sum + (claimDueCents(rates, c) ?? 0), 0));
144	    }
145	    return out;
146	  });
147	  /** The sheet's periods, by from-date. */
148	  protected readonly periods = signal<Period[]>([]);
149	  /** Each period's due-total in cents, by period id: the dues (n/a ones skipped) of the OPEN and
150	   *  SETTLED claims whose date falls in it. */
